def solve(path: str) -> str:
    """Simplify an absolute Unix path.
    Resolve '.' and '..', collapse multiple slashes, and remove trailing slash.
    The root remains '/'. Leading/trailing whitespace is ignored, but internal spaces are preserved.
    """
    # Trim whitespace around the whole path (input may contain leading/trailing spaces)
    path = path.strip()
    stack = []
    for part in path.split('/'):
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)
    return '/' + '/'.join(stack) if stack else '/'

def solve(n):
    # Return the number of prime numbers strictly less than n.
    if n <= 2:
        return 0
    limit = n - 1
    sieve = bytearray(b'\x01') * (limit + 1)
    sieve[0:2] = b'\x00\x00'
    import math
    for p in range(2, int(math.isqrt(limit)) + 1):
        if sieve[p]:
            start = p * p
            step = p
            sieve[start:limit+1:step] = b'\x00' * ((limit - start) // step + 1)
    return sum(sieve)

