def solve(meetings):
    # robust version handling unsorted inner structures and ensuring proper comparison
    # Convert each meeting to (start, end) tuple ensuring start <= end by swapping if needed
    processed = []
    for m in meetings:
        if not isinstance(m, (list, tuple)) or len(m) != 2:
            continue  # ignore invalid entries
        s, e = m[0], m[1]
        # ensure numeric
        try:
            s = int(s)
            e = int(e)
        except Exception:
            continue
        if s > e:
            s, e = e, s
        processed.append((s, e))
    processed.sort(key=lambda x: x[1])
    count = 0
    last_end = -10**18
    for s, e in processed:
        if s >= last_end:
            count += 1
            last_end = e
    return count

