def solve(s: str) -> bool:
    """Return True if *s* is a valid IPv4 address.
    The address must consist of exactly four decimal numbers between 0 and 255,
    separated by dots. Leading zeros are not allowed unless the number is exactly
    "0". Whitespace around the address is ignored.
    """
    if not isinstance(s, str):
        return False
    s = s.strip()
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for p in parts:
        if not p.isdigit():
            return False
        # No leading zeros unless the part is exactly "0"
        if len(p) > 1 and p[0] == '0':
            return False
        val = int(p)
        if not (0 <= val <= 255):
            return False
    return True

