def solve(grid):
    """Count islands in a binary grid.
    1's are land, 0's water. Connected 4-directionally.
    Empty grid returns 0.
    """
    if not grid:
        return 0
    n = len(grid)
    m = max((len(row) for row in grid), default=0)
    if m == 0:
        return 0
    visited = [[False]*len(row) for row in grid]
    count = 0
    from collections import deque
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if val and not visited[i][j]:
                count += 1
                q = deque([(i, j)])
                visited[i][j] = True
                while q:
                    r, c = q.popleft()
                    for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        nr, nc = r+dr, c+dc
                        if 0 <= nr < n and 0 <= nc < len(grid[nr]):
                            if grid[nr][nc] and not visited[nr][nc]:
                                visited[nr][nc] = True
