def solve(grid):
    # Handle empty grid or grid with empty rows
    if not grid:
        return 0
    visited = set()
    def is_land(val):
        return val == 1 or val == '1' or val is True
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if (i, j) in visited:
                continue
            visited.add((i, j))
            for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
                ni, nj = i+di, j+dj
                if 0 <= ni < len(grid) and 0 <= nj < len(grid[ni]) and (ni, nj) not in visited and is_land(grid[ni][nj]):
                    stack.append((ni, nj))
    count = 0
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if is_land(val) and (i, j) not in visited:
                dfs(i, j)
                count += 1
    return count

