def solve(grid):
    """Count islands in a binary grid.
    Cells representing land can be int 1, string '1', or True.
    Connected 4-directionally. Empty grid returns 0.
    """
    if not grid:
        return 0
    n = len(grid)
    # Determine max column length for safety
    m = max((len(row) for row in grid), default=0)
    if m == 0:
        return 0
    visited = [[False]*len(row) for row in grid]
    def is_land(val):
        if isinstance(val, bool):
            return val
        if isinstance(val, int):
            return val == 1
        if isinstance(val, str):
            return val.strip() == '1'
        return False
    from collections import deque
    count = 0
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if is_land(val) and not visited[i][j]:
                count += 1
                q = deque([(i, j)])
                visited[i][j] = True
                while q:
                    r, c = q.popleft()
                    for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        nr, nc = r+dr, c+dc
                        if 0 <= nr < n and 0 <= nc < len(grid[nr]):
                            if is_land(grid[nr][nc]) and not visited[nr][nc]:
                                visited[nr][nc] = True
                                q.append((nr, nc))
    return count

