def solve(tokens):
    """Evaluate Reverse Polish Notation.
    tokens: list of strings, each either an integer or one of '+', '-', '*', '/'.
    Division should truncate toward zero.
    """
    stack = []
    ops = {'+', '-', '*', '/'}
    for tok in tokens:
        if tok in ops:
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                res = a + b
            elif tok == '-':
                res = a - b
            elif tok == '*':
                res = a * b
            else:  # division
                # Python's int division truncates toward zero when using int(a / b)
                res = int(a / b)
            stack.append(res)
        else:
            stack.append(int(tok))
    return stack[0] if stack else 0

